{
  "up": "Select molecule_dictionary.chembl_id as molecule_chembl_id, molecule_dictionary.pref_name as molecule_name, molecule_dictionary.max_phase as max_phase, molecule_dictionary.molecule_type as molecule_type, compound_structures.canonical_smiles as canonical_smiles Join compound_records on molecule_dictionary.molregno = compound_records.molregno Join docs on compound_records.doc_id = docs.doc_id Left Join compound_structures on molecule_dictionary.molregno = compound_structures.molregno Filter docs.chembl_id = 'CHEMBL1697781' Return molecule_chembl_id, molecule_name, max_phase, molecule_type, canonical_smiles Sort by molecule_chembl_id"
}
